        def good(ds):
            return all(a < b for a, b in zip(ds, ds[1:])) or all(a > b for a, b in zip(ds, ds[1:]))
        ans = 0
        for v in range(l, r + 1):
            ds = list(map(int, str(v)))
            if good(ds) or good(list(map(int, str(sum(ds))))):
                ans += 1
        return ans

