public:
    bool good(vector<int>& d) {
        bool inc = true, dec = true;
        for (int i = 1; i < (int)d.size(); i++) {
            if (d[i] <= d[i-1]) inc = false;
            if (d[i] >= d[i-1]) dec = false;
        }
        return inc || dec;
    }
    long long countFancyNumbers(long long l, long long r) {
        long long ans = 0;
        for (long long v = l; v <= r; v++) {
            vector<int> d; long long t = v; int s = 0;
            while (t) { d.push_back(t % 10); s += t % 10; t /= 10; }
            reverse(d.begin(), d.end());
            vector<int> sd; t = s; while (t) { sd.push_back(t % 10); t /= 10; }
            reverse(sd.begin(), sd.end());
            if (good(d) || good(sd)) ans++;
        }
        return ans;
    }
};

