class Solution {
    private boolean good(int[] d) {
        boolean inc = true, dec = true;
        for (int i = 1; i < d.length; i++) {
            if (d[i] <= d[i-1]) inc = false;
            if (d[i] >= d[i-1]) dec = false;
        }
        return inc || dec;
    }
    public long countFancyNumbers(long l, long r) {
        long ans = 0;
        for (long v = l; v <= r; v++) {
            StringBuilder a = new StringBuilder(), b = new StringBuilder();
            long t = v; int s = 0;
            while (t > 0) { a.append(t % 10); s += t % 10; t /= 10; }
            t = s; while (t > 0) { b.append(t % 10); t /= 10; }
            int[] d = a.reverse().toString().chars().map(c -> c - '0').toArray();
            int[] sd = b.reverse().toString().chars().map(c -> c - '0').toArray();
            if (good(d) || good(sd)) ans++;
        }
        return ans;
    }
}

