from functools import lru_cache
class Solution:
    def countFancyNumbers(self, l, r):
        MAXS = 145
        goodS = [False] * MAXS
        for v in range(MAXS):
            d = list(map(int, str(v)))
            goodS[v] = len(d) == 1 or all(a < b for a, b in zip(d, d[1:])) or all(a > b for a, b in zip(d, d[1:]))

        @lru_cache(maxsize=None)
        def free(rem, last, dr, s):
            if rem == 0:
                return 1 if (dr != 3 or goodS[s]) else 0
            tot = 0
            for d in range(10):
                if dr == 0: nd = 0
                elif dr == 1: nd = 1 if d > last else 3
                elif dr == 2: nd = 2 if d < last else 3
                else: nd = 3
                if dr == 0 and last >= 0:
                    nd = 1 if d > last else (2 if d < last else 3)
                tot += free(rem - 1, d, nd, s + d)
            return tot

        def count(x):
            if x <= 0: return 0
            ds = list(map(int, str(x)))
            L = len(ds)
            ans = 0
            for first in range(1, 10):
                ans += free(L - 1, first, 0, first)
            last, dr, s = -1, 0, 0
            for i, ch in enumerate(ds):
                hi = int(ch)
                for d in range(1 if i == 0 else 0, hi):
                    if last == -1: nd = 0
                    elif dr == 0: nd = 1 if d > last else (2 if d < last else 3)
                    elif dr == 1: nd = 1 if d > last else 3
                    elif dr == 2: nd = 2 if d < last else 3
                    else: nd = 3
                    ans += free(L - 1 - i, d, nd, s + d)
                if last == -1: dr = 0
                elif dr == 0: dr = 0
                last, s = hi, s + hi
                if last >= 0 and len(str(x)) > 1:
                    pass
            # recompute direction properly along the tight path
            last, dr, s = -1, 0, 0
            digs = []
            for i, ch in enumerate(ds):
                hi = int(ch)
                for d in range(1 if i == 0 else 0, hi):
                    tmp = digs + [d]
                    ndr = 0
                    for k in range(1, len(tmp)):
                        if ndr == 0: ndr = 1 if tmp[k] > tmp[k-1] else (2 if tmp[k] < tmp[k-1] else 3)
                        elif ndr == 1: ndr = 1 if tmp[k] > tmp[k-1] else 3
                        elif ndr == 2: ndr = 2 if tmp[k] < tmp[k-1] else 3
                        else: ndr = 3
                    ans += free(L - 1 - i, d, ndr, sum(tmp))
                digs.append(hi)
            ndr = 0
            for k in range(1, len(digs)):
                if ndr == 0: ndr = 1 if digs[k] > digs[k-1] else (2 if digs[k] < digs[k-1] else 3)
                elif ndr == 1: ndr = 1 if digs[k] > digs[k-1] else 3
                elif ndr == 2: ndr = 2 if digs[k] < digs[k-1] else 3
                else: ndr = 3
            if ndr != 3 or goodS[sum(digs)]: ans += 1
            return ans

        return count(r) - count(l - 1)

