class Solution {
public:
    bool goodS[150];
    static long long memo[17][11][4][146];
    bool seen[17][11][4][146];
    long long free_(int rem, int last, int dr, int s) {
        if (rem == 0) return (dr != 3 || goodS[s]) ? 1 : 0;
        if (seen[rem][last][dr][s]) return memo[rem][last][dr][s];
        seen[rem][last][dr][s] = true;
        long long tot = 0;
        for (int d = 0; d < 10; d++) {
            int nd = dr;
            if (last >= 0) {
                if (dr == 0) nd = d > last ? 1 : (d < last ? 2 : 3);
                else if (dr == 1) nd = d > last ? 1 : 3;
                else if (dr == 2) nd = d < last ? 2 : 3;
                else nd = 3;
            }
            tot += free_(rem - 1, d, nd, s + d);
        }
        return memo[rem][last][dr][s] = tot;
    }
    long long count(long long x) {
        if (x <= 0) return 0;
        memset(seen, 0, sizeof(seen));
        string ds = to_string(x);
        int L = ds.size();
        long long ans = 0;
        for (int f = 1; f <= 9; f++) ans += free_(L - 1, f, 0, f);
        vector<int> digs;
        for (int i = 0; i < L; i++) {
            int hi = ds[i] - '0';
            for (int d = (i == 0 ? 1 : 0); d < hi; d++) {
                vector<int> tmp = digs; tmp.push_back(d);
                int ndr = 0;
                for (int k = 1; k < (int)tmp.size(); k++) {
                    if (ndr == 0) ndr = tmp[k] > tmp[k-1] ? 1 : (tmp[k] < tmp[k-1] ? 2 : 3);
                    else if (ndr == 1) ndr = tmp[k] > tmp[k-1] ? 1 : 3;
                    else if (ndr == 2) ndr = tmp[k] < tmp[k-1] ? 2 : 3;
                    else ndr = 3;
                }
                int sm = 0; for (int v : tmp) sm += v;
                ans += free_(L - 1 - i, d, ndr, sm);
            }
            digs.push_back(hi);
        }
        int ndr = 0, sm = 0;
        for (int k = 0; k < L; k++) {
            sm += digs[k];
            if (k) {
                if (ndr == 0) ndr = digs[k] > digs[k-1] ? 1 : (digs[k] < digs[k-1] ? 2 : 3);
                else if (ndr == 1) ndr = digs[k] > digs[k-1] ? 1 : 3;
                else if (ndr == 2) ndr = digs[k] < digs[k-1] ? 2 : 3;
                else ndr = 3;
            }
        }
        if (ndr != 3 || goodS[sm]) ans++;
        return ans;
    }
    long long countFancyNumbers(long long l, long long r) {
        for (int v = 0; v < 150; v++) {
            string s = to_string(v);
            bool inc = true, dec = true;
            for (int i = 1; i < (int)s.size(); i++) {
                if (s[i] <= s[i-1]) inc = false;
                if (s[i] >= s[i-1]) dec = false;
            }
            goodS[v] = s.size() == 1 || inc || dec;
        }
        return count(r) - count(l - 1);
    }
};
